// Rich notes keep a plain-text copy for legacy readers and search.
let researchQuill=null,researchEditorSerial=0,researchQuillPromise=null;
function loadResearchQuill(){
 if(window.Quill)return Promise.resolve(window.Quill);if(researchQuillPromise)return researchQuillPromise;
 researchQuillPromise=Promise.all([new Promise((resolve,reject)=>{const l=document.createElement('link');l.rel='stylesheet';l.href='vendor/quill/quill-2.0.3.snow.css';l.onload=resolve;l.onerror=()=>{l.remove();reject(Error('편집기 스타일을 불러오지 못했어요.'))};document.head.append(l)}),new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/quill/quill-2.0.3.js';s.onload=resolve;s.onerror=()=>{s.remove();reject(Error('편집기를 불러오지 못했어요.'))};document.head.append(s)})]).then(()=>window.Quill).catch(e=>{researchQuillPromise=null;throw e});return researchQuillPromise;
}
function validatedResearchDelta(value,plain){
 try{const d=typeof value==='string'?JSON.parse(value):value;if(!d||!Array.isArray(d.ops)||d.ops.length>20000)return null;let text='';for(const op of d.ops){if(!op||typeof op.insert!=='string'||Object.keys(op).some(k=>!['insert','attributes'].includes(k)))return null;text+=op.insert;if(op.attributes){if(typeof op.attributes!=='object'||Array.isArray(op.attributes))return null;for(const [k,v] of Object.entries(op.attributes)){if(!['bold','italic','blockquote','list','link'].includes(k))return null;if(['bold','italic','blockquote'].includes(k)&&typeof v!=='boolean')return null;if(k==='list'&&!['ordered','bullet'].includes(v))return null;if(k==='link'&&(typeof v!=='string'||!/^https?:\/\//i.test(v)||v.length>2000))return null}}}return text.trim()===String(plain||'').trim()?d:null}catch{return null}
}
function researchSavePayload(){const value=$('#note-rich').value,body=$('#note-body').value,delta=value?validatedResearchDelta(value,body):null;if(value&&!delta)throw Error('글 내용과 서식을 확인하지 못했어요. 다시 열어 주세요.');const note=editingId?notes.find(n=>n.id===editingId):null;return {body_delta:delta,...(note?{expected_updated_at:note.updated_at||null}:{})}}
function syncResearchEditorText(){if(!researchQuill)return;researchQuill.setText($('#note-body').value,'silent');$('#note-rich').value=''}
function setupResearchEditor(note){
 const serial=++researchEditorSerial,dialog=$('#edit-dialog'),body=$('#note-body'),rich=$('#note-rich'),controls=$('#note-edit-controls');researchQuill=null;document.querySelector('#research-quill-wrap')?.remove();body.hidden=false;body.required=true;controls.innerHTML='';const author=$('#author');document.querySelector('#research-author-switch')?.remove();author.hidden=false;
 if(!isPersonalStudyRoute())return;const authors=document.createElement('div');authors.id='research-author-switch';authors.setAttribute('role','group');authors.setAttribute('aria-label','작성자');authors.innerHTML=[['mine','민수'],['bora','보라']].map(([id,label])=>`<button type="button" data-research-author="${id}" aria-pressed="${author.value===id}">${personIdentity(id)}<span>${label}</span></button>`).join('');author.hidden=true;author.after(authors);authors.querySelectorAll('button').forEach(button=>button.onclick=()=>{author.value=button.dataset.researchAuthor;authors.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));author.dispatchEvent(new Event('change',{bubbles:true}))});
 if(note){controls.innerHTML=`<button type="button" class="research-connect" data-study-links="${esc(note.id)}">연구 연결 수정</button><button type="button" class="research-delete">이 기록 삭제</button>`;bindPersonalLinks();controls.querySelector('.research-delete').onclick=async()=>{if(!confirm('이 기록과 첨부 이미지를 삭제할까요?'))return;const button=controls.querySelector('.research-delete');button.disabled=true;try{const pin=await personalStudyCredential();if(pin===null)return;await change('delete',{id:note.id},pin);try{localStorage.removeItem(draftKey())}catch{}imagesChanged=false;dialog.close();cleanup();await load();personView(currentPerson)}catch(error){$('#form-message').textContent=error.message||'삭제하지 못했어요.'}finally{button.disabled=false}}}
 const wrap=document.createElement('div');wrap.id='research-quill-wrap';wrap.hidden=true;wrap.innerHTML='<div class="research-toolbar" aria-label="글 서식"><button type="button" class="ql-bold" aria-label="굵게"></button><button type="button" class="ql-italic" aria-label="기울임"></button><button type="button" class="ql-list" value="bullet" aria-label="목록"></button><button type="button" class="ql-list" value="ordered" aria-label="번호 목록"></button><button type="button" class="ql-blockquote" aria-label="인용"></button><button type="button" class="ql-link" aria-label="링크"></button></div><div class="research-editor"></div>';body.closest('label').after(wrap);
 loadResearchQuill().then(Quill=>{if(serial!==researchEditorSerial||!dialog.open||!wrap.isConnected||researchSaving||document.activeElement===body)return;const q=new Quill(wrap.querySelector('.research-editor'),{theme:'snow',placeholder:'기억하고 싶은 내용을 자유롭게 적어 보세요.',formats:['bold','italic','list','blockquote','link'],modules:{toolbar:wrap.querySelector('.research-toolbar')}});const delta=validatedResearchDelta(rich.value,body.value);if(delta)q.setContents(delta,'silent');else{q.setText(body.value,'silent');rich.value=''}q.root.setAttribute('aria-label','묵상 내용');researchQuill=q;body.required=false;body.hidden=true;wrap.hidden=false;q.on('text-change',(_d,_o,source)=>{if(source!=='user')return;body.value=q.getText().replace(/\n$/,'');rich.value=JSON.stringify(q.getContents());body.dispatchEvent(new Event('input',{bubbles:true}))})}).catch(()=>{wrap.remove()});
}
function researchNoteExpansion(node){const button=node.nextElementSibling;if(!button||!button.classList.contains('note-expand'))return;requestAnimationFrame(()=>{if(!node.isConnected)return;button.hidden=node.scrollHeight<=node.clientHeight+2;button.onclick=()=>{const expanded=node.classList.toggle('expanded');button.textContent=expanded?'접기':'더 보기';button.setAttribute('aria-expanded',String(expanded))}})}
function hydrateResearchNotes(list){for(const n of list){const node=document.querySelector('[data-rich-note="'+CSS.escape(n.id)+'"]');if(node)researchNoteExpansion(node)}const rich=list.filter(n=>n.body_delta&&validatedResearchDelta(n.body_delta,n.body));if(!rich.length)return;loadResearchQuill().then(Quill=>{for(const n of rich){const node=document.querySelector('[data-rich-note="'+CSS.escape(n.id)+'"]');if(!node||!node.isConnected)continue;const delta=validatedResearchDelta(n.body_delta,n.body);if(!delta)continue;try{node.textContent='';const q=new Quill(node,{theme:'snow',readOnly:true,formats:['bold','italic','list','blockquote','link'],modules:{toolbar:false}});q.setContents(delta,'silent');researchNoteExpansion(node)}catch{node.textContent=n.body;researchNoteExpansion(node)}}}).catch(()=>{})}
// Editing the plain fallback must not leave formatting attached to changed text.
document.addEventListener('input',event=>{if(event.target?.id==='note-body'&&!researchQuill){const rich=document.querySelector('#note-rich');if(rich)rich.value=''}},true);
